                                              && callee ps i j c cj 64 1 (nth i G.BLS []) [(VPE, 0, ELit 8)] NEWS_D None (-176)
                                              && CL.ps_reg_is ps 10 A0E && CL.ps_reg_is ps 11 A1E && CL.ps_reg_is ps 12 VPE && has cells (KWord (SA FE 56) 8 FLE) && CC.has_cell (CC.cp_know c) KZF)
                 else if (Z.eqb pc PC_VINT || Z.eqb pc PC_VSTR) then      (* [comment removed for export] *)
                                             (Nat.eqb i 2 && Nat.leb 3 j && Nat.leb j 8 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && CHA.frames_eqb (nth j FFS []) (nth i FFS [])
                                              && callee ps i j c cj XKA.VIS 0 (nth i G.BLS []) WENC NEWS_F (Some (ELit 1)) (-128) && has cells (KWord (SA FE 56) 8 FLE)
                                              && CL.ps_reg_is ps 10 VE
                                              && (Z.eqb pc PC_VINT || (CL.ps_reg_is ps 11 SVA && CL.ps_reg_is ps 12 (ELit 2) && has cells (KWord (SA FE 32) 8 (EVar 32)) && has cells (KWord (SA FE 40) 8 (EVar 33))
                                                                      && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 4)) 1 (ELit 0)) && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 5)) 1 (ELit 0))))
                                              && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) && has cells (KZero (SA (CHA.SRL3 S2E) SBz) (ELit 3)))
                 else if Z.eqb pc PC_AV then (Nat.leb 3 i && Nat.leb i 8 && Nat.eqb j (i + 6) && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && callee ps i j c cj 1152 0 [] AV_W NEWS_A None (-128)
                                              && CL.ps_reg_is ps 10 PE && CL.ps_reg_is ps 11 EE && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA FE 56) 8 FLE))
                 else false)%bool
            | None => false end
        | None => false end
  end.
